// This file is not generated by Speakeasy — it gives 'vf auth signup' (see
// internal/oauth) a way to list the new account's workspaces. It lives here
// because internal/oauth cannot import internal/client, which imports it.

package cli

import (
	"context"

	"github.com/spf13/cobra"
	"github.com/voiceflow/cli/internal/client"
	"github.com/voiceflow/cli/internal/oauth"
)

// listSignupWorkspaces lists the workspaces of the account signed in on cmd.
func listSignupWorkspaces(ctx context.Context, cmd *cobra.Command) ([]oauth.Workspace, error) {
	s, err := client.NewClient(cmd)
	if err != nil {
		return nil, err
	}
	res, err := s.Workspace.List(ctx)
	if err != nil {
		return nil, err
	}
	var workspaces []oauth.Workspace
	for _, ws := range res.StableWorkspaceListResponse.GetWorkspaces() {
		workspaces = append(workspaces, oauth.Workspace{ID: ws.ID, Name: ws.Name})
	}
	return workspaces, nil
}
